<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'
import { generationTypeConfigApi, settingsApi, workflowApi } from '@/api/modules'
import GlassCard from '@/v2/components/GlassCard.vue'
import StatusBadge from '@/v2/components/StatusBadge.vue'
import V2Button from '@/v2/components/V2Button.vue'
import V2Field from '@/v2/components/V2Field.vue'
import WorkflowMappingWorkspace from './WorkflowMappingWorkspace.vue'
import type { ConfigValidation, ConfigVersion, GenerationConfig, ParameterConfig } from './model'
import { cloneConfig, parameterTypes } from './model'

const route = useRoute(); const router = useRouter(); const typeId = Number(route.params.id)
const steps = ['基础信息', '页面配置', '参数设计', '参数联动', '尺寸与方案', '工作流绑定', '输出与预览', '检查与发布']
const step = ref(0); const loading = ref(true); const saving = ref(false); const publishing = ref(false)
const dirty = ref(false); const notice = ref(''); const error = ref('')
const draftId = ref<number|null>(null); const config = ref<GenerationConfig|null>(null)
const validation = ref<ConfigValidation|null>(null); const workflows = ref<any[]>([]); const versions = ref<ConfigVersion[]>([])
const selectedParameter = ref(0); const diffResult = ref<any>(null); const previewMode = ref<'desktop'|'mobile'>('desktop')
const selectOptions = ref<Record<string,{label:string;options:any[];default_value:any}>>({})
const workflowImportOpen = ref(false); const workflowImportStep = ref<'upload'|'mapping'>('upload')
const workflowFileInput = ref<HTMLInputElement|null>(null); const workflowRawJson = ref(''); const workflowJson = ref<Record<string,any>>({})
const workflowParseResult = ref<any>(null); const workflowName = ref(''); const workflowMappings = ref<any[]>([])
const workflowOutputMapping = ref('{}'); const importingWorkflow = ref(false)
const editingWorkflowId = ref<number|null>(null); const editingWorkflowVersionId = ref<number|null>(null)
let ready = false

const currentParameter = computed(() => config.value?.parameters[selectedParameter.value] || null)
const issueCount = computed(() => (validation.value?.errors.length || 0) + (validation.value?.warnings.length || 0))
const publishable = computed(() => validation.value?.valid === true && !saving.value && !publishing.value)
const defaultBinding = computed(() => config.value?.workflow_bindings.find((item) => item.is_default))
const parameterSelectSources = computed(() => Object.entries(selectOptions.value).filter(([key]) => !['image_size','video_size'].includes(key)))
const designedParameters = computed(() => config.value?.parameters || [])
const mediaParameterTypes = ['image', 'video', 'audio']
const normalParameterTypes = computed(() => parameterTypes.filter(item => !mediaParameterTypes.includes(item[0])))
const mediaTypeOptions = computed(() => parameterTypes.filter(item => mediaParameterTypes.includes(item[0])))
const normalParameters = computed(() => designedParameters.value.filter(item => item.group !== 'media'))
const mediaParameters = computed(() => designedParameters.value.filter(item => item.group === 'media'))
const mappingPresets = computed(() => config.value?.workflow_mapping_presets || [])

watch(config, () => { if (ready) dirty.value = true }, { deep: true })
onBeforeRouteLeave(() => !dirty.value || confirm('当前配置尚未保存，确认离开？'))

async function load() {
  loading.value = true; error.value = ''
  try {
    const [draft, maintainedOptions] = await Promise.all([generationTypeConfigApi.draft(typeId), settingsApi.getSelectOptions()])
    selectOptions.value = maintainedOptions
    draftId.value = draft.id; config.value = cloneConfig(draft.config)
    config.value!.workflow_mapping_presets ||= []
    config.value!.parameters.forEach(parameter => { parameter.group ||= mediaParameterTypes.includes(parameter.type) ? 'media' : 'parameter' })
    reindexMediaParameters()
    workflows.value = await workflowApi.list({ generation_type_code: config.value!.basic.code })
    versions.value = await generationTypeConfigApi.versions(typeId)
    ready = true; dirty.value = false
    await check()
  } catch (event: any) { error.value = event.response?.data?.message || '配置加载失败' }
  finally { loading.value = false }
}
async function save() {
  if (!config.value) return
  saving.value = true; error.value = ''
  try { const result = await generationTypeConfigApi.saveDraft(typeId, config.value as any); draftId.value = result.id; dirty.value = false; notice.value = '草稿已保存' }
  catch (event: any) { error.value = event.response?.data?.message || '草稿保存失败' }
  finally { saving.value = false }
}
async function check() { if (config.value) validation.value = await generationTypeConfigApi.validate(typeId, config.value as any) }
async function publish() {
  await save(); await check(); if (!validation.value?.valid) { step.value = 7; return }
  publishing.value = true
  try { const result = await generationTypeConfigApi.publish(typeId); notice.value = `版本 v${result.version} 已发布`; dirty.value = false; await load(); step.value = 7 }
  catch (event: any) { error.value = event.response?.data?.message || '发布失败' }
  finally { publishing.value = false }
}
async function rollback(version: ConfigVersion) {
  if (!confirm(`回滚到 v${version.version}？系统会创建一个新的发布版本。`)) return
  await generationTypeConfigApi.rollback(typeId, version.id); notice.value = `已从 v${version.version} 创建回滚版本`; await load(); step.value = 7
}
async function showDiff(version: ConfigVersion) {
  const current = versions.value.find((item) => item.status === 'published')
  if (!current || current.id === version.id) { diffResult.value = { changes: [] }; return }
  diffResult.value = await generationTypeConfigApi.diff(typeId, version.id, current.id)
}
function addParameter(group: 'parameter' | 'media' = 'parameter') {
  config.value?.parameters.push({ key: `${group}_${(config.value?.parameters.length || 0) + 1}`, type: group === 'media' ? 'image' : 'text', label: group === 'media' ? '新素材' : '新参数', group, ...(group === 'media' ? { media_order: mediaParameters.value.length + 1, multiple: false, max_items: 1 } : {}) })
  selectedParameter.value = (config.value?.parameters.length || 1) - 1
}
function addPreset(kind:'image_size'|'video_size'|'video_length'|'video_fps'){
  if(!config.value)return
  const source=selectOptions.value[kind]
  if(kind==='image_size'||kind==='video_size'){
    const size=String(source?.default_value||(kind==='image_size'?'1088x1920':'576x1024'));const [width,height]=size.split('x').map(Number)
    const existingWidth=config.value.parameters.find(item=>item.key==='width');const existingHeight=config.value.parameters.find(item=>item.key==='height')
    if(existingWidth||existingHeight){notice.value='宽度或高度参数已经存在，生成页面会自动合并为尺寸选择。';return}
    config.value.parameters.push({key:'width',type:'int',label:'宽度',group:'parameter',default:width,required:true,help:`由${source?.label||'尺寸维护项'}统一选择`},{key:'height',type:'int',label:'高度',group:'parameter',default:height,required:true,help:`由${source?.label||'尺寸维护项'}统一选择`})
    selectedParameter.value=config.value.parameters.length-2
  }else{
    const key=kind==='video_length'?'length':'fps';if(config.value.parameters.some(item=>item.key===key)){notice.value=`参数 ${key} 已存在`;return}
    config.value.parameters.push({key,type:'select',label:source?.label||(kind==='video_length'?'视频帧数':'视频帧率'),group:'parameter',default:source?.default_value,options_from:kind,required:true})
    selectedParameter.value=config.value.parameters.length-1
  }
}
function duplicateParameter(index: number) {
  if (!config.value) return; const copy = cloneConfig(config.value.parameters[index]); copy.key += '_copy'; config.value.parameters.splice(index + 1, 0, copy); selectedParameter.value = index + 1; reindexMediaParameters()
}
function removeParameter(index: number) { if (config.value && confirm('删除这个参数？')) { config.value.parameters.splice(index, 1); reindexMediaParameters(); selectedParameter.value = Math.max(0, index - 1) } }
function moveParameter(index: number, offset: number) { if (!config.value) return; const target=index+offset; if(target<0||target>=config.value.parameters.length)return; const [item]=config.value.parameters.splice(index,1); config.value.parameters.splice(target,0,item); selectedParameter.value=target }
function parameterIndex(parameter: ParameterConfig){return config.value?.parameters.indexOf(parameter) ?? -1}
function reindexMediaParameters(){mediaParameters.value.forEach((parameter,index)=>parameter.media_order=index+1)}
function moveWithinGroup(parameter: ParameterConfig, offset: number){if(!config.value)return;const group=parameter.group==='media'?'media':'parameter';const peers=config.value.parameters.filter(item=>(item.group==='media'?'media':'parameter')===group);const peerIndex=peers.indexOf(parameter);const targetPeer=peers[peerIndex+offset];if(!targetPeer)return;const sourceIndex=config.value.parameters.indexOf(parameter);const targetIndex=config.value.parameters.indexOf(targetPeer);config.value.parameters.splice(sourceIndex,1);config.value.parameters.splice(targetIndex,0,parameter);selectedParameter.value=config.value.parameters.indexOf(parameter);reindexMediaParameters()}
function addOption(parameter: ParameterConfig) { (parameter.options ||= []).push({ label: '新选项', value: '' }) }
function addScheme() { config.value?.parameter_schemes.push({ id: crypto.randomUUID(), name: '新方案', is_default: !config.value.parameter_schemes.length, params: {} }) }
function setDefaultScheme(index:number){config.value?.parameter_schemes.forEach((item,i)=>item.is_default=i===index)}
function bindWorkflow(workflow:any) { if(!config.value||!workflow.current_version_id)return; if(config.value.workflow_bindings.some(v=>v.workflow_version_id===workflow.current_version_id))return; config.value.workflow_bindings.push({workflow_id:workflow.id,workflow_version_id:workflow.current_version_id,is_default:!config.value.workflow_bindings.length}) }
function setDefaultWorkflow(index:number){config.value?.workflow_bindings.forEach((item,i)=>item.is_default=i===index)}
function removeBinding(index:number){config.value?.workflow_bindings.splice(index,1);if(config.value?.workflow_bindings.length&&!config.value.workflow_bindings.some(v=>v.is_default))config.value.workflow_bindings[0].is_default=true}
const workflowNodeOptions = computed(() => (workflowParseResult.value?.nodes || []).map((node:any) => ({ value:String(node.id), label:`${node.id} · ${node.title || node.class_type}` })))
const inputFieldCandidates:Record<string,string[]>={int:['value','Float','text'],bool:['value','Float','text'],select:['value','Float','text'],seed:['value','Float','text'],float:['Float','value','text'],image:['image'],video:['video'],audio:['audio'],text:['text','value','Float'],textarea:['text','value','Float']}
function workflowInputOptions(mapping:any){const inputs=workflowJson.value?.[String(mapping.node)]?.inputs;if(!inputs||typeof inputs!=='object'||Array.isArray(inputs))return[];const options=Object.keys(inputs).map(field=>({label:field,value:`inputs.${field}`}));if(mapping.path&&!options.some(option=>option.value===mapping.path))options.unshift({label:`${String(mapping.path).replace(/^inputs\./,'')}（原映射）`,value:mapping.path});return options}
function workflowNodeChanged(mapping:any,nodeId:string){mapping.node=String(nodeId||'');const inputs=workflowJson.value?.[mapping.node]?.inputs;if(!inputs||typeof inputs!=='object'){mapping.path='';return}const field=(inputFieldCandidates[mapping.type]||['value']).find(name=>Object.prototype.hasOwnProperty.call(inputs,name));mapping.path=field?`inputs.${field}`:'';if(!field)notice.value=`节点 ${mapping.node} 没有找到适合“${mapping.label||mapping.key}”的属性，请从参数名称下拉框手工选择。`}
function workflowParameterChanged(mapping:any,key:string){const parameter=config.value?.parameters.find(item=>item.key===key);if(!parameter)return;const node=mapping.node,path=mapping.path;Object.keys(mapping).forEach(name=>delete mapping[name]);Object.assign(mapping,cloneConfig(parameter),{node,path});workflowNodeChanged(mapping,node)}
function saveMappingPreset(name:string){if(!config.value)return;try{const presets=(config.value.workflow_mapping_presets ||= []);presets.push({id:crypto.randomUUID(),name,workflow_id:editingWorkflowId.value||undefined,workflow_version_id:editingWorkflowVersionId.value||undefined,mappings:workflowMappings.value.map(item=>({key:item.key,node:String(item.node||''),path:String(item.path||'')})),output_mapping:JSON.parse(workflowOutputMapping.value||'{}')});notice.value=`映射预设“${name}”已保存到当前配置草稿`}catch{error.value='输出节点映射不是有效 JSON，暂时无法保存预设'}}
function applyMappingPreset(id:string){const preset=mappingPresets.value.find(item=>item.id===id);if(!preset)return;const savedByKey=Object.fromEntries(preset.mappings.map(item=>[item.key,item]));workflowMappings.value.forEach(mapping=>{const saved=savedByKey[mapping.key];if(saved){mapping.node=saved.node;mapping.path=saved.path}});workflowOutputMapping.value=JSON.stringify(preset.output_mapping||{},null,2);notice.value=`已应用映射预设“${preset.name}”`}
function deleteMappingPreset(id:string){if(!config.value)return;const index=(config.value.workflow_mapping_presets||[]).findIndex(item=>item.id===id);if(index>=0&&confirm('删除这个映射预设？'))config.value.workflow_mapping_presets!.splice(index,1)}
function resetWorkflowImport(){workflowImportStep.value='upload';workflowRawJson.value='';workflowJson.value={};workflowParseResult.value=null;workflowName.value='';workflowMappings.value=[];workflowOutputMapping.value='{}';editingWorkflowId.value=null;editingWorkflowVersionId.value=null;if(workflowFileInput.value)workflowFileInput.value.value=''}
function closeWorkflowImport(){workflowImportOpen.value=false;resetWorkflowImport()}
async function workflowFileChanged(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;workflowRawJson.value=await file.text();if(!workflowName.value)workflowName.value=file.name.replace(/\.json$/i,'');await parseWorkflow()}
async function parseWorkflow(){if(!config.value)return;error.value='';try{const parsed=JSON.parse(workflowRawJson.value);if(!parsed||Array.isArray(parsed)||typeof parsed!=='object')throw new Error('JSON 根节点必须是对象');workflowJson.value=parsed;const result=await workflowApi.parse(parsed,config.value.basic.code,config.value.parameters);workflowParseResult.value=result;workflowName.value=workflowName.value||result.suggested_name||`${config.value.basic.name}工作流`;workflowMappings.value=result.param_schema||[];workflowOutputMapping.value=JSON.stringify(result.output_mapping||{},null,2);workflowImportStep.value='mapping'}catch(event:any){error.value=event.response?.data?.detail||event.message||'工作流解析失败'}}
async function editBoundWorkflow(binding:any){const workflow=workflows.value.find(item=>item.id===binding.workflow_id);if(!workflow)return;error.value='';try{const detail=await workflowApi.getVersionDetail(workflow.id,binding.workflow_version_id);editingWorkflowId.value=workflow.id;editingWorkflowVersionId.value=binding.workflow_version_id;workflowName.value=workflow.name;workflowJson.value=detail.api_json||{};workflowRawJson.value=JSON.stringify(workflowJson.value,null,2);workflowParseResult.value={nodes:detail.nodes||[]};const savedByKey=Object.fromEntries((detail.param_schema||[]).map((item:any)=>[item.key,item]));workflowMappings.value=(config.value?.parameters||[]).map(parameter=>({...cloneConfig(parameter),node:savedByKey[parameter.key]?.node||'',path:savedByKey[parameter.key]?.path||''}));workflowOutputMapping.value=JSON.stringify(detail.output_mapping||{},null,2);workflowImportStep.value='mapping';workflowImportOpen.value=true}catch(event:any){error.value=event.response?.data?.detail||'工作流版本加载失败'}}
async function saveImportedWorkflow(){if(!config.value||!workflowName.value.trim())return;const missing=workflowMappings.value.filter(item=>!item.node||!item.path);if(missing.length&&!confirm(`仍有 ${missing.length} 个参数未完成映射，确认保存？`))return;importingWorkflow.value=true;error.value='';try{const outputMapping=JSON.parse(workflowOutputMapping.value||'{}');let workflow:any;let version:any;if(editingWorkflowId.value){workflow=workflows.value.find(item=>item.id===editingWorkflowId.value);await workflowApi.update(editingWorkflowId.value,{name:workflowName.value.trim()});version=await workflowApi.addVersion(editingWorkflowId.value,{api_json:workflowJson.value,param_schema:workflowMappings.value,output_mapping:outputMapping});const binding=config.value.workflow_bindings.find(item=>item.workflow_id===editingWorkflowId.value&&item.workflow_version_id===editingWorkflowVersionId.value)||config.value.workflow_bindings.find(item=>item.workflow_id===editingWorkflowId.value);if(binding)binding.workflow_version_id=version.id;notice.value=`工作流「${workflowName.value.trim()}」已创建新版本 #${version.id}，参数映射和绑定已同步更新。`}else{workflow=await workflowApi.create({name:workflowName.value.trim(),description:`由 V2 生成类型配置「${config.value.basic.name}」上传`,media_type:config.value.basic.media_type,generation_type_id:typeId});version=await workflowApi.addVersion(workflow.id,{api_json:workflowJson.value,param_schema:workflowMappings.value,output_mapping:outputMapping});config.value.workflow_bindings.forEach(item=>item.is_default=false);config.value.workflow_bindings.push({workflow_id:workflow.id,workflow_version_id:version.id,is_default:true});notice.value=`工作流「${workflow.name}」已上传、匹配并设为默认，保存草稿后生效。`}workflows.value=await workflowApi.list({generation_type_code:config.value.basic.code});closeWorkflowImport();await check()}catch(event:any){error.value=event.response?.data?.detail||event.message||'工作流保存失败'}finally{importingWorkflow.value=false}}
function visible(parameter: ParameterConfig) { const rule=parameter.visible_when;if(!rule)return true;const source=config.value?.parameters.find(p=>p.key===rule.key);if(!source)return false;if(rule.operator==='truthy')return Boolean(source.default);if(rule.operator==='not_equals')return source.default!==rule.value;return source.default===rule.value }
function next(){step.value=Math.min(7,step.value+1)} function previous(){step.value=Math.max(0,step.value-1)}
onMounted(load)
</script>

<template>
  <div class="config-editor">
    <div class="editor-heading"><div><button class="back" @click="router.push('/v2/settings/generation-types')">← 返回类型列表</button><h1>{{ config?.basic.name || '生成类型配置' }}</h1><p v-if="config"><code>{{ config.basic.code }}</code> · 草稿 #{{ draftId }}</p></div><div class="heading-actions"><span v-if="dirty" class="dirty">● 未保存</span><V2Button @click="save">{{ saving?'保存中…':'保存草稿' }}</V2Button><V2Button variant="primary" :disabled="!publishable" @click="publish">{{ publishing?'发布中…':'发布配置' }}</V2Button></div></div>
    <div v-if="notice" class="notice success">{{ notice }}</div><div v-if="error" class="notice danger">{{ error }}</div>
    <div v-if="loading" class="loading">配置加载中…</div>
    <template v-else-if="config">
      <nav class="stepper"><button v-for="(label,index) in steps" :key="label" :class="{active:step===index,done:step>index}" @click="step=index"><b>{{ index+1 }}</b><span>{{ label }}</span></button></nav>
      <div class="editor-layout">
        <main>
          <GlassCard v-if="step===0"><div class="section-title"><div><h2>基础信息</h2><p>名称与菜单顺序发布后生效，编码和媒体类型不可修改。</p></div></div><div class="form-grid"><V2Field label="类型名称" required><input v-model="config.basic.name" /></V2Field><V2Field label="类型编码" hint="发布后不可修改"><input v-model="config.basic.code" disabled /></V2Field><V2Field label="媒体类型"><select v-model="config.basic.media_type" disabled><option value="image">图片</option><option value="video">视频</option><option value="audio">音频</option></select></V2Field><V2Field label="菜单顺序"><input v-model.number="config.basic.menu_order" type="number" /></V2Field></div></GlassCard>
          <GlassCard v-else-if="step===1"><div class="section-title"><div><h2>页面配置</h2><p>定义生成页在 Web 与移动端上的标题和说明。</p></div></div><div class="form-grid"><V2Field label="页面标题" required><input v-model="config.page.title" /></V2Field><V2Field label="页面图标"><input v-model="config.page.icon" placeholder="例如 ✦" /></V2Field><V2Field label="页面布局"><select v-model="config.page.layout"><option value="list">任务列表</option><option value="cards">任务卡片</option></select></V2Field><V2Field class="wide" label="页面说明"><textarea v-model="config.page.description" rows="4" /></V2Field></div></GlassCard>
          <GlassCard v-else-if="step===2" padding="sm">
            <div class="section-title"><div><h2>参数设计器</h2><p>这里是生成页参数的唯一来源；工作流导入只映射，不会创建另一套参数。</p></div></div>
            <div class="preset-parameters"><span>快速增加维护项</span><V2Button v-if="config.basic.media_type==='image'" variant="ghost" @click="addPreset('image_size')">＋ 图片尺寸</V2Button><V2Button v-if="config.basic.media_type==='video'" variant="ghost" @click="addPreset('video_size')">＋ 视频尺寸</V2Button><V2Button v-if="config.basic.media_type==='video'" variant="ghost" @click="addPreset('video_length')">＋ 视频帧数</V2Button><V2Button v-if="config.basic.media_type==='video'" variant="ghost" @click="addPreset('video_fps')">＋ 视频帧率</V2Button></div>
            <div class="parameter-designer grouped">
              <div class="parameter-groups">
                <section><header><div><b>提示词和参数</b><small>文本、数值、开关及选项</small></div><button @click="addParameter('parameter')">＋</button></header><div class="parameter-list"><button v-for="parameter in normalParameters" :key="parameter.key" :class="{active:selectedParameter===parameterIndex(parameter)}" @click="selectedParameter=parameterIndex(parameter)"><span>{{ parameter.label || '未命名' }}<small>{{ parameter.key }} · {{ parameter.options_from ? `维护项 ${parameter.options_from}` : parameter.type }}</small></span><i @click.stop="moveWithinGroup(parameter,-1)">↑</i><i @click.stop="moveWithinGroup(parameter,1)">↓</i><i @click.stop="duplicateParameter(parameterIndex(parameter))">⧉</i><i class="delete" @click.stop="removeParameter(parameterIndex(parameter))">×</i></button><p v-if="!normalParameters.length" class="group-empty">暂无参数</p></div></section>
                <section><header><div><b>素材节点和顺序</b><small>图片、视频、音频输入</small></div><button @click="addParameter('media')">＋</button></header><div class="parameter-list media"><button v-for="(parameter,index) in mediaParameters" :key="parameter.key" :class="{active:selectedParameter===parameterIndex(parameter)}" @click="selectedParameter=parameterIndex(parameter)"><em>{{ String(index+1).padStart(2,'0') }}</em><span>{{ parameter.label || '未命名' }}<small>{{ parameter.key }} · {{ parameter.type }}</small></span><i @click.stop="moveWithinGroup(parameter,-1)">↑</i><i @click.stop="moveWithinGroup(parameter,1)">↓</i><i class="delete" @click.stop="removeParameter(parameterIndex(parameter))">×</i></button><p v-if="!mediaParameters.length" class="group-empty">暂无素材节点</p></div></section>
              </div>
              <div v-if="currentParameter" class="parameter-form"><div class="parameter-form-title"><div><b>{{ currentParameter.group==='media'?'素材节点设置':'提示词与参数设置' }}</b><small>{{ currentParameter.group==='media'?`当前顺序：${currentParameter.media_order}`:'保存后用于生成页面及工作流映射' }}</small></div></div><div class="form-grid"><V2Field label="参数名称"><input v-model="currentParameter.label" /></V2Field><V2Field label="参数键"><input v-model="currentParameter.key" /></V2Field><V2Field label="控件类型"><select v-model="currentParameter.type"><option v-for="item in currentParameter.group==='media'?mediaTypeOptions:normalParameterTypes" :key="item[0]" :value="item[0]">{{ item[1] }}</option></select></V2Field><template v-if="currentParameter.group==='media'"><V2Field label="允许多选"><select v-model="currentParameter.multiple"><option :value="false">单个素材</option><option :value="true">多个素材</option></select></V2Field><V2Field v-if="currentParameter.multiple" label="最多选择"><input v-model.number="currentParameter.max_items" type="number" min="1" max="20" /></V2Field></template><template v-else><V2Field v-if="currentParameter.type==='select'" label="选项来源"><select v-model="currentParameter.options_from"><option :value="undefined">页面内自定义</option><option v-for="entry in parameterSelectSources" :key="entry[0]" :value="entry[0]">系统维护 · {{ entry[1].label }}</option></select></V2Field><V2Field label="默认值"><select v-if="currentParameter.type==='bool'" v-model="currentParameter.default"><option :value="true">开启</option><option :value="false">关闭</option></select><select v-else-if="currentParameter.type==='select'&&currentParameter.options_from" v-model="currentParameter.default"><option v-for="option in selectOptions[currentParameter.options_from]?.options||[]" :key="option.value" :value="option.value">{{ option.label }}</option></select><input v-else-if="['int','float','seed','slider'].includes(currentParameter.type)" v-model.number="currentParameter.default" type="number" /><input v-else v-model="currentParameter.default" /></V2Field><V2Field label="最小值"><input v-model.number="currentParameter.min" type="number" /></V2Field><V2Field label="最大值"><input v-model.number="currentParameter.max" type="number" /></V2Field><V2Field label="步长"><input v-model.number="currentParameter.step" type="number" /></V2Field><V2Field label="单位"><input v-model="currentParameter.unit" /></V2Field></template><V2Field label="必填"><select v-model="currentParameter.required"><option :value="true">是</option><option :value="false">否</option></select></V2Field><V2Field class="wide" label="帮助说明"><textarea v-model="currentParameter.help" rows="2" /></V2Field></div><div v-if="currentParameter.group!=='media'&&currentParameter.type==='select'&&!currentParameter.options_from" class="options"><header><h3>下拉选项</h3><V2Button @click="addOption(currentParameter)">添加选项</V2Button></header><div v-for="(option,index) in currentParameter.options" :key="index"><input v-model="option.label" placeholder="显示名称"/><input v-model="option.value" placeholder="选项值"/><button @click="currentParameter.options?.splice(index,1)">×</button></div></div><div v-else-if="currentParameter.options_from" class="maintained-info">该参数使用“{{ selectOptions[currentParameter.options_from]?.label }}”维护项，当前默认值：{{ selectOptions[currentParameter.options_from]?.default_value }}。</div></div>
